// Race condition: two async operations on shared state
let balance = 1000;
const sleep = ms => new Promise(r => setTimeout(r, ms));

async function withdraw(amount, label) {
  const current = balance;           // READ
  await sleep(10);                   // simulated DB round-trip — other tasks run here
  balance = current - amount;        // WRITE (with a stale 'current'!)
  console.log(`${label}: withdrew ${amount}, new balance: ${balance}`);
}

// ── FIX 1: serialize with an async mutex (a promise chain) ──────────────
function createMutex() {
  let tail = Promise.resolve();      // the end of the waiting line
  return function withLock(fn) {
    const run = tail.then(fn);       // start fn only after the previous holder finishes
    tail = run.catch(() => {});      // a failed task must not jam the line
    return run;                      // the caller still sees fn's result or error
  };
}

// ── FIX 2 (N slots instead of 1): a counting semaphore ──────────────────
function createSemaphore(n) {
  let count = n;
  const waiters = [];
  return {
    wait() {
      if (count > 0) { count--; return Promise.resolve(); }
      return new Promise(resolve => waiters.push(resolve)); // no slot — queue up
    },
    signal() {
      const next = waiters.shift();
      if (next) next();              // hand the slot straight to the next waiter (FIFO)
      else count++;
    },
  };
}

async function main() {
  // UNSAFE: both reads happen before either write
  await Promise.all([withdraw(200, 'Alice'), withdraw(300, 'Bob')]);
  console.log('Final balance (wrong):', balance);
  // Expected 500. Both read 1000: Alice writes 800, then Bob overwrites it with 700.
  // Final: 700 — Alice's withdrawal is silently lost.

  balance = 1000;
  const lock = createMutex();
  await Promise.all([
    lock(() => withdraw(200, 'Alice (safe)')),
    lock(() => withdraw(300, 'Bob   (safe)')),
  ]);
  console.log('Final balance (safe):', balance); // 500 — Bob read 800, not 1000

  const dbPool = createSemaphore(3); // at most 3 concurrent DB operations
  let active = 0, peak = 0;
  async function queryDatabase(id) {
    await dbPool.wait();             // wait if 3 others are already running
    try {
      active++; peak = Math.max(peak, active);
      await sleep(50);               // simulated query
    } finally {
      active--;
      dbPool.signal();               // always release, even if the query throws
    }
  }
  await Promise.all(Array.from({ length: 8 }, (_, i) => queryDatabase(i)));
  console.log('Peak concurrent queries:', peak); // 3
}

main();

// Conceptual (threaded-language style): assumes account objects expose
// lock()/unlock() and an async tryLock(ms) that resolves to true/false.
const sleep = ms => new Promise(r => setTimeout(r, ms));

// ── Strategy 1: Lock Ordering (breaks Circular Wait) ──────────────────────────
// WRONG: lock order depends on argument order
function transferWrong(from, to, amount) {
  from.lock();   // Thread A: transfer(acct42 → acct99) locks 42
                 // Thread B: transfer(acct99 → acct42) locks 99
  to.lock();     // A now waits for 99 while B waits for 42 — DEADLOCK
  from.balance -= amount;
  to.balance   += amount;
  to.unlock();
  from.unlock();
}

// CORRECT: always lock the lower account ID first, whatever the direction
function transferSafe(from, to, amount) {
  const [first, second] = from.id < to.id ? [from, to] : [to, from];
  first.lock();
  try {
    second.lock();
    try {
      // Every thread agrees on the order → no cycle in the wait-for graph
      from.balance -= amount;
      to.balance   += amount;
    } finally {
      second.unlock();
    }
  } finally {
    first.unlock();
  }
}

// ── Strategy 2: try-lock, release, back off, retry (breaks No Preemption) ─────
async function transferWithTimeout(from, to, amount, maxRetries = 5) {
  for (let attempt = 0; attempt < maxRetries; attempt++) {
    if (await from.tryLock(200)) {            // wait at most 200 ms
      try {
        if (await to.tryLock(200)) {
          try {
            from.balance -= amount;
            to.balance   += amount;
            return { success: true, attempt };
          } finally {
            to.unlock();
          }
        }
        // Could not get `to`: fall through — the finally below gives up `from`
      } finally {
        from.unlock();                        // we "preempt" ourselves
      }
    }
    // Exponential backoff with jitter: ~50, 100, 200, 400 ms … plus randomness
    await sleep(50 * 2 ** attempt + Math.random() * 50);
  }
  throw new Error(`Transfer failed after ${maxRetries} attempts — likely contention or deadlock`);
}
